function t(lang, key) {
  var pack = I18N[lang] || I18N.zh;
  if (pack[key] !== undefined) return pack[key];
  if (I18N.zh[key] !== undefined) return I18N.zh[key];
  return key;
}

/* 语言回退：ja 缺内容时用 en，en 缺用 zh */
function pick(lang, obj) {
  if (!obj) return '';
  if (obj[lang] !== undefined && obj[lang] !== null && obj[lang] !== '') return obj[lang];
  if (lang === 'ja') {
    if (obj.en !== undefined && obj.en !== null && obj.en !== '') return obj.en;
  }
  if (obj.en !== undefined && obj.en !== null && obj.en !== '') return obj.en;
  return obj.zh !== undefined ? obj.zh : '';
}

/* 判断某字段是否发生了语言回退（用于显示提示） */
function isFallback(lang, obj) {
  if (!obj) return false;
  var own = obj[lang];
  if (own && (Array.isArray(own) ? own.length : String(own).length)) return false;
  return true;
}

var i18nExport = { I18N: I18N, t: t, pick: pick, isFallback: isFallback };

if (typeof module !== 'undefined' && module.exports) { module.exports = i18nExport; }
if (typeof window !== 'undefined') {
  window.I18N = I18N;
  window.t = t;
  window.pick = pick;
  window.isFallback = isFallback;
}
